<script module>  export const manifiesto = {    id: 'ventas',    nombre: 'Ventas',    icono: 'cart',    grupo: 'negocio',    orden: 1,    tablas: { ventas: '++id, fecha, anulada', lotes: '++id, productoId, varianteId, fecha, costo, compraId' },  };</script><script>  import { onMount } from 'svelte';  import { listar } from '../../core/db.js';  import { bus } from '../../core/bus.js';  import {    avisar,    confirmar,    preguntar,    pedirPIN,    marcarCambiosSinGuardar,    limpiarCambiosSinGuardar,  } from '../../core/state.svelte.js';  import { n, m, q, fmt, fmtCant, fmtFH, stockVariante, calcFIFOVariante, fuzzySearchScored } from '../../core/util.js';  import { ConversionService } from '../../services/ConversionService.js';  import { VentaService } from '../../services/VentaService.js';  import { ProductoVarianteService } from '../../services/ProductoVarianteService.js';  import { obtenerPeriodosCerrados } from '../../core/periodos.js';  import Icono from '../../core/Icono.svelte';  let productos = $state([]);  let variantes = $state([]);  let lotes = $state([]);  let ventas = $state([]);  let periodosCerrados = $state([]);  let busq = $state('');  let focusBusq = $state(false);  let carrito = $state([]);  let procesando = $state(false);  let cobro = $state({ activo: false, total: 0, recibido: '', vuelto: 0 });  let busqHist = $state('');  let busqDebounced = $state('');  let busqHistDebounced = $state('');  let paginaHist = $state(1);  const itemsPorPagina = 20;  $effect(() => { const t = setTimeout(() => (busqDebounced = busq), 200); return () => clearTimeout(t); });  $effect(() => { const t = setTimeout(() => (busqHistDebounced = busqHist), 200); return () => clearTimeout(t); });  $effect(() => { busqHistDebounced; paginaHist = 1; });  $effect(() => { if (carrito.length > 0) marcarCambiosSinGuardar(); else limpiarCambiosSinGuardar(); });  const variantesActivas = $derived(variantes.filter((v) => !v.archivado));  const resultados = $derived((() => {    const base = variantesActivas.filter((v) => stockVariante(lotes, v.id) > 0);    const scored = fuzzySearchScored(base, busqDebounced, (v) => {      const p = productos.find((x) => x.id === v.productoId);      return v.nombre + ' ' + (v.codigo || '') + ' ' + (p?.nombre || '');    });    return scored.map(s => s.item).slice(0, 12);  })());  const ventasFiltradas = $derived((() => {    let v = ventas.slice().sort((a, b) => {      if (a.anulada !== b.anulada) return a.anulada ? 1 : -1;      return new Date(b.fecha) - new Date(a.fecha);    });    const qry = busqHistDebounced.toLowerCase().trim();    if (qry) v = v.filter((x) => x.items.some((i) => i.nombre.toLowerCase().includes(qry)));    return v;  })());  const ventasPaginadas = $derived(ventasFiltradas.slice((paginaHist - 1) * itemsPorPagina, paginaHist * itemsPorPagina));  const totalPaginas = $derived(Math.max(1, Math.ceil(ventasFiltradas.length / itemsPorPagina)));  const totalCarrito = $derived(m(carrito.reduce((s, it) => s + n(it.precio) * n(it.cant), 0)));  const gananciaCarrito = $derived(m((() => {    const cache = new Map();    return carrito.reduce((s, it) => {      const key = it.varianteId + '|' + n(it.cant);      let costoTotal;      if (cache.has(key)) { costoTotal = cache.get(key); }      else {        const f = calcFIFOVariante(lotes, it.varianteId, n(it.cant));        if (f.error) return s;        costoTotal = f.costoTotal;        cache.set(key, costoTotal);      }      return s + (n(it.precio) * n(it.cant) - costoTotal);    }, 0);  })()));  async function recargar() {    [productos, variantes, lotes, ventas] = await Promise.all([      listar('productos'), listar('productoVariantes'), listar('lotes'), listar('ventas')    ]);    periodosCerrados = await obtenerPeriodosCerrados();  }  function esCerrado(fechaIso) {    const f = new Date(fechaIso);    return periodosCerrados.some((p) => new Date(p.inicio) <= f && f <= new Date(p.fin));  }  onMount(() => { recargar(); const off = bus.on('recargar', recargar); return () => off(); });  function nombreProductoBase(varianteId) {    const v = variantes.find((x) => x.id === varianteId);    if (!v) return '';    const p = productos.find((x) => x.id === v.productoId);    return p ? p.nombre : '';  }  function agregar(v) {    const s = stockVariante(lotes, v.id);    if (s <= 0) return avisar('Sin stock', 'bad');    const ex = carrito.find((i) => i.varianteId === v.id);    if (ex) {      if (n(ex.cant) < s) {        ex.cant = String(n(ex.cant) + 1);        ex.precio = String(ProductoVarianteService.precioParaCantidad(v, n(ex.cant)));      } else return avisar('Stock maximo', 'warn');    } else {      carrito.push({        productoId: v.productoId,        varianteId: v.id,        nombre: v.nombre,        nombreBase: nombreProductoBase(v.id),        precio: String(ProductoVarianteService.precioParaCantidad(v, 1)),        cant: '1',        unidad: v.unidad || '',        esCaja: v.esCaja,        unidadesPorCaja: v.unidadesPorCaja,      });    }    busq = '';    focusBusq = false;  }  function cambiarCant(it, dir) {    let val = n(it.cant) + dir;    if (it.unidad && ['kg', 'lb', 'gr', 'litro', 'm'].includes(it.unidad)) {      val = n(it.cant) + dir * 0.5;    }    const max = stockVariante(lotes, it.varianteId);    if (val > max) return avisar('Stock maximo alcanzado', 'warn');    if (val < 0) val = 0;    it.cant = String(val);    const v = variantes.find((x) => x.id === it.varianteId);    if (v) { it.precio = String(ProductoVarianteService.precioParaCantidad(v, val)); }  }  function validarCant(it) {    let val = n(it.cant);    const max = stockVariante(lotes, it.varianteId);    if (val > max) { val = max; avisar('Cantidad ajustada al stock disponible', 'warn'); }    if (val < 0) val = 0;    it.cant = String(val);    const v = variantes.find((x) => x.id === it.varianteId);    if (v) { it.precio = String(ProductoVarianteService.precioParaCantidad(v, val)); }  }  function subTotal(it) { return m(n(it.precio) * n(it.cant)); }  function precioAhorro(it) {    const v = variantes.find((x) => x.id === it.varianteId);    if (!v) return null;    const precioBase = n(v.precioBase);    const precioActual = n(it.precio);    if (precioActual < precioBase) {      return { ahorroUnit: m(precioBase - precioActual), ahorroTotal: m((precioBase - precioActual) * n(it.cant)) };    }    return null;  }  function stockDescompuesto(varianteId) {    const v = variantes.find((x) => x.id === varianteId);    if (!v || !v.esCaja || !v.unidadesPorCaja) return null;    const s = stockVariante(lotes, varianteId);    return ConversionService.descomponerStock(s, v.unidadesPorCaja);  }  function iniciarCobro() {    const inv = carrito.filter((it) => n(it.cant) <= 0);    if (inv.length) return avisar('Todas las cantidades deben ser > 0', 'bad');    cobro = { activo: true, total: totalCarrito, recibido: '', vuelto: 0 };  }  function calcVuelto() {    const rec = n(cobro.recibido);    cobro.vuelto = rec > 0 ? m(rec - cobro.total) : 0;  }  async function procesarVenta() {    procesando = true;    try {      const { venta, total, ganancia } = await VentaService.procesar(carrito, lotes);      await recargar();      carrito = [];      cobro.activo = false;      avisar('Venta exitosa: ' + fmt(total));      bus.emit('recargar');    } catch (e) {      avisar(e.message, 'bad');    } finally { procesando = false; }  }  async function anularVenta(v) {    const pinOk = await pedirPIN();    if (!pinOk) return;    const ok = await confirmar('Anular venta', 'Anular venta por ' + fmt(v.total) + '? Se restaura el stock.');    if (!ok) return;    await VentaService.anular(v, lotes);    await recargar();    bus.emit('recargar');    avisar('Venta anulada');  }  function onKeydown(e) {    if (e.key === 'F1') { e.preventDefault(); focusBusq = true; setTimeout(() => document.querySelector('input[placeholder*=&quot;Buscar&quot;]')?.focus(), 50); }    if (e.key === 'Enter' && focusBusq && resultados.length > 0) { e.preventDefault(); agregar(resultados[0]); }    if (e.key === 'Escape') {      if (cobro.activo) { cobro.activo = false; }      else if (focusBusq) { focusBusq = false; busq = ''; }      else if (carrito.length > 0) { carrito = []; }    }    if (e.key === 'F2' && carrito.length > 0 && !cobro.activo) { e.preventDefault(); iniciarCobro(); }    if (e.key === 'F3' && cobro.activo) { e.preventDefault(); cobro.recibido = cobro.total.toFixed(2); calcVuelto(); }  }</script><svelte:window onkeydown={onKeydown} /><div class='modulo'>  <!-- Atajos hint --><div class='bg-background rounded-lg px-3 py-2 mb-3 text-[0.65rem] text-muted flex flex-wrap gap-x-3 gap-y-1'>  <span><kbd class='px-1 py-0.5 bg-card border border-border rounded text-[0.6rem]'>F1</kbd> Buscar</span>  <span><kbd class='px-1 py-0.5 bg-card border border-border rounded text-[0.6rem]'>Enter</kbd> Agregar</span>  <span><kbd class='px-1 py-0.5 bg-card border border-border rounded text-[0.6rem]'>F2</kbd> Cobrar</span>  <span><kbd class='px-1 py-0.5 bg-card border border-border rounded text-[0.6rem]'>F3</kbd> Exacto</span>  <span><kbd class='px-1 py-0.5 bg-card border border-border rounded text-[0.6rem]'>Esc</kbd> Limpiar</span></div>  <!-- Nueva Venta --><div class='bg-card rounded-[var(--radius-lg)] p-4 shadow-[var(--color-shadow)] mb-3'>  <div class='flex items-center gap-2 font-extrabold text-primary mb-3'>    <Icono nombre='cart' size={18} />    Nueva Venta  </div>  <div class='relative mb-3'>    <Icono nombre='search' size={18} class='absolute left-3 top-1/2 -translate-y-1/2 text-muted' />    <input class='w-full pl-10 pr-3.5 py-3 border border-border rounded-[var(--radius-md)] bg-card text-text text-base outline-none focus:border-primary focus:shadow-[0_0_0_3px_rgba(33,150,243,0.15)]' type='text' placeholder='Buscar variante por nombre, SKU o producto... (F1)' bind:value={busq} onfocus={() => (focusBusq = true)} />  </div>  {#if focusBusq}    <button class='fixed inset-0 z-[5] bg-transparent border-none cursor-default' onclick={() => (focusBusq = false)} ontouchstart={() => (focusBusq = false)} aria-hidden='true' tabindex='-1'></button>    <div class='border border-border rounded-[var(--radius-md)] bg-card max-h-64 overflow-y-auto mb-3 shadow-[var(--color-shadow)] relative z-10'>      <div class='flex justify-between items-center px-3 py-2.5 text-xs font-extrabold text-muted border-b border-border sticky top-0 bg-card'>        <span>{resultados.length} resultado(s)</span>        <button class='bg-transparent border-none text-danger font-extrabold text-lg cursor-pointer leading-none' onclick={() => { focusBusq = false; busq = ''; }}>×</button>      </div>      {#if resultados.length === 0}        <div class='text-center text-muted py-5 text-sm'>Sin coincidencias (o sin stock)</div>      {:else}        {#each resultados as v, i}          {@const p = productos.find((x) => x.id === v.productoId)}          {@const s = stockVariante(lotes, v.id)}          <button class='w-full flex justify-between items-center px-3.5 py-3 text-left border-b border-border last:border-0 text-sm cursor-pointer hover:bg-background active:bg-background transition-colors' onclick={() => agregar(v)}>            <div class='min-w-0 flex-1'>              <div class='font-bold text-sm'>{v.nombre}</div>              <div class='text-xs text-muted'>{p?.nombre || ''} {#if v.codigo}· {v.codigo}{/if}</div>            </div>            <div class='text-right flex-shrink-0'>              <span class='text-muted text-xs whitespace-nowrap'>Stock {fmtCant(s)} {v.unidad || ''} · {fmt(v.precioBase)}</span>              {#if i === 0}<span class='text-[0.6rem] text-primary ml-1'>(Enter)</span>{/if}            </div>          </button>        {/each}      {/if}    </div>  {/if}  {#if carrito.length > 0}    <div class='mt-3 space-y-2'>      {#each carrito as it, i}        {@const v = variantes.find((x) => x.id === it.varianteId)}        {@const ahorro = precioAhorro(it)}        {@const dec = stockDescompuesto(it.varianteId)}        <div class='bg-background rounded-[var(--radius-md)] p-3 border border-border/50'>          <div class='flex justify-between items-start gap-2 mb-2'>            <div class='font-bold text-sm truncate flex-1'>              {it.nombre}              {#if it.nombreBase}<span class='text-muted font-normal text-xs'> ({it.nombreBase})</span>{/if}              {#if it.esCaja}<span class='inline-block px-1.5 py-0.5 rounded text-[0.6rem] font-extrabold text-white bg-primary ml-1'>CAJA</span>{/if}            </div>            <button class='w-8 h-8 rounded-full bg-danger/10 text-danger border-none flex items-center justify-center cursor-pointer flex-shrink-0 active:scale-[0.92] transition-transform' aria-label='Eliminar del carrito' onclick={() => carrito.splice(i, 1)}>              <Icono nombre='x' size={14} color='#dc2626' />            </button>          </div>          {#if dec}            <div class='text-[0.65rem] text-muted mb-2'>Disponible: {dec.cajas} cajas + {fmtCant(dec.unidades)} unidades</div>          {/if}          <div class='flex items-center gap-2 flex-wrap'>            <div class='flex items-center bg-card border border-border rounded-lg overflow-hidden'>              <button class='w-9 h-9 bg-background border-none text-primary font-extrabold text-lg cursor-pointer flex items-center justify-center active:scale-[0.92] transition-transform touch-manipulation' aria-label='Disminuir cantidad' onclick={() => cambiarCant(it, -1)}>                <Icono nombre='minus' size={14} />              </button>              <input class='w-14 text-center border-none bg-transparent text-sm py-1 font-bold' type='text' bind:value={it.cant} onblur={() => validarCant(it)} />              <button class='w-9 h-9 bg-background border-none text-primary font-extrabold text-lg cursor-pointer flex items-center justify-center active:scale-[0.92] transition-transform touch-manipulation' aria-label='Aumentar cantidad' onclick={() => cambiarCant(it, 1)}>                <Icono nombre='plus' size={14} />              </button>            </div>            <span class='text-xs text-muted'>@</span>            <input class='w-20 text-center border border-border rounded-lg bg-card text-sm py-1.5 px-1 font-bold' type='number' step='0.01' bind:value={it.precio} />            <div class='ml-auto text-right'>              <div class='text-xs text-muted'>{fmt(it.precio)} × {fmtCant(it.cant)} {it.unidad || ''}</div>              <div class='text-sm font-extrabold text-primary'>{fmt(subTotal(it))}</div>            </div>          </div>          {#if ahorro}            <div class='text-xs text-success mt-1 flex items-center gap-1'>              <Icono nombre='tag' size={10} /> Ahorro: {fmt(ahorro.ahorroTotal)} ({fmt(ahorro.ahorroUnit)} c/u)            </div>          {/if}          {#if v && v.preciosEscalonados && v.preciosEscalonados.length > 0}            <div class='text-[0.65rem] text-muted mt-1'>Escalones: {#each v.preciosEscalonados as pe}{pe.cantidadMinima}+ @{fmt(pe.precioUnitario)} · {/each}</div>          {/if}        </div>      {/each}      <!-- Total --><div class='flex justify-between items-center bg-gradient-to-r from-success/10 to-success/5 border border-success/30 rounded-[var(--radius-md)] p-4 my-3 font-extrabold text-success'>        <div class='flex items-center gap-2'>          <Icono nombre='check' size={16} />          <span>TOTAL</span>        </div>        <span class='text-xl'>{fmt(totalCarrito)}</span>      </div>      <div class='flex justify-between text-xs text-success mb-3 px-1'>        <span>Ganancia estimada</span>        <span class='font-bold'>{fmt(gananciaCarrito)}</span>      </div>      <button class='w-full py-3 rounded-[var(--radius-md)] bg-success text-white font-extrabold text-sm mb-2 active:scale-[0.97] transition-transform disabled:opacity-50' onclick={iniciarCobro} disabled={procesando}>        <Icono nombre='wallet' size={16} color='#fff' />        {procesando ? 'Procesando...' : 'Cobrar Venta (F2)'}      </button>      <button class='w-full py-3 rounded-[var(--radius-md)] border border-border bg-transparent text-text font-extrabold text-sm active:scale-[0.97] transition-transform' onclick={() => (carrito = [])}>        <Icono nombre='trash' size={14} />        Limpiar carrito (Esc)      </button>    </div>  {:else if !focusBusq}    <div class='text-center text-muted py-8 text-sm'>      <Icono nombre='search' size={32} class='mx-auto mb-2 opacity-30' />      Toca el buscador o presiona F1 para buscar    </div>  {/if}</div>  <!-- Historial --><div class='bg-card rounded-[var(--radius-lg)] p-4 shadow-[var(--color-shadow)]'>  <div class='flex items-center gap-2 font-extrabold text-primary mb-3'>    <Icono nombre='history' size={18} />    Historial de Ventas  </div>  <div class='relative mb-3'>    <Icono nombre='search' size={16} class='absolute left-3 top-1/2 -translate-y-1/2 text-muted' />    <input class='w-full pl-9 pr-3.5 py-2.5 border border-border rounded-[var(--radius-md)] bg-card text-text text-sm outline-none focus:border-primary focus:shadow-[0_0_0_3px_rgba(33,150,243,0.15)]' type='text' placeholder='Buscar en historial...' bind:value={busqHist} />  </div>  {#if ventasPaginadas.length === 0}    <div class='text-center text-muted py-6 text-sm'>Sin ventas</div>  {:else}    <div class='space-y-0'>      {#each ventasPaginadas as v}        <div class='flex justify-between items-center gap-2 py-3 border-b border-border {v.anulada ? 'opacity-50' : ''}'>          <div class='min-w-0 flex-1'>            <div class='font-bold text-sm {v.anulada ? 'line-through' : ''}'>              {v.items.map((x) => x.nombre + ' ×' + fmtCant(x.cantidad) + (x.unidad ? ' ' + x.unidad : '')).join(', ')}            </div>            <div class='flex items-center gap-2 mt-0.5'>              <span class='text-xs text-muted'>{fmtFH(v.fecha)}</span>              <span class='text-xs font-bold text-primary'>{fmt(v.total)}</span>              <span class='text-xs text-success'>+{fmt(v.ganancia)}</span>            </div>          </div>          {#if !v.anulada && !esCerrado(v.fecha)}            <button class='inline-flex items-center gap-1 px-2.5 py-1.5 rounded-md bg-danger/10 text-danger text-xs font-extrabold border-none cursor-pointer active:scale-[0.92] transition-transform' aria-label='Anular venta' onclick={() => anularVenta(v)}>              <Icono nombre='x' size={12} color='#dc2626' />              Anular            </button>          {:else if esCerrado(v.fecha)}            <span class='inline-block px-2 py-0.5 rounded-full text-[0.6rem] font-extrabold text-white bg-warning'>CERRADO</span>          {:else}            <span class='inline-block px-2 py-0.5 rounded-full text-[0.6rem] font-extrabold text-white bg-muted'>ANULADA</span>          {/if}        </div>      {/each}    </div>    {#if totalPaginas > 1}      <div class='flex justify-center items-center gap-2 mt-3 text-sm'>        <button class='px-3 py-1 rounded-md border border-border bg-card disabled:opacity-30 active:scale-[0.95] transition-transform' onclick={() => paginaHist--} disabled={paginaHist <= 1}>←</button>        <span class='text-muted'>{paginaHist} / {totalPaginas}</span>        <button class='px-3 py-1 rounded-md border border-border bg-card disabled:opacity-30 active:scale-[0.95] transition-transform' onclick={() => paginaHist++} disabled={paginaHist >= totalPaginas}>→</button>      </div>    {/if}  {/if}</div>  <!-- Modal Cobro -->{#if cobro.activo}<div class='fixed inset-0 bg-black/50 z-[100] flex items-center justify-center p-4 no-print' role='dialog' tabindex='-1' aria-modal='true' onkeydown={(e) => e.key === 'Escape' && (cobro.activo = false)}>  <button class='absolute inset-0 w-full h-full bg-transparent border-none cursor-default' onclick={() => (cobro.activo = false)} aria-label='Cerrar dialogo'></button>  <div class='bg-card rounded-[var(--radius-lg)] p-5 w-full max-w-sm shadow-[0_10px_40px_rgba(0,0,0,0.3)] animate-pop relative z-10' role='document'>    <div class='flex items-center gap-2 font-extrabold text-primary text-lg mb-3'>      <Icono nombre='wallet' size={20} />      Cobrar Venta    </div>    <div class='bg-primary/5 rounded-xl p-4 mb-3 text-center'>      <div class='text-xs text-muted mb-1'>Total a Pagar</div>      <div class='text-3xl font-extrabold text-primary'>{fmt(cobro.total)}</div>    </div>    <input class='w-full px-3.5 py-3 border border-border rounded-[var(--radius-md)] bg-card text-text text-base outline-none focus:border-primary focus:shadow-[0_0_0_3px_rgba(33,150,243,0.15)] mb-2' type='number' inputmode='decimal' step='0.01' placeholder='Efectivo recibido (opcional)' bind:value={cobro.recibido} oninput={calcVuelto} />    <button class='w-full py-2 rounded-[var(--radius-md)] border border-border bg-transparent text-text font-bold text-sm mb-3 active:scale-[0.95] transition-transform' onclick={() => { cobro.recibido = cobro.total.toFixed(2); calcVuelto(); }}>Pagar Exacto (F3)</button>    {#if cobro.recibido && cobro.vuelto >= 0}      <div class='text-center text-2xl font-extrabold text-success my-2 p-4 bg-success/10 rounded-[var(--radius-md)]'>        Vuelto: {fmt(cobro.vuelto)}      </div>    {/if}    <button class='w-full py-3 rounded-[var(--radius-md)] bg-success text-white font-extrabold text-sm mb-2 active:scale-[0.97] transition-transform disabled:opacity-50' onclick={procesarVenta} disabled={procesando}>      <Icono nombre='check' size={16} color='#fff' />      {procesando ? 'Procesando...' : 'Confirmar Pago'}    </button>    <button class='w-full py-3 rounded-[var(--radius-md)] border border-border bg-transparent text-text font-extrabold text-sm active:scale-[0.97] transition-transform' onclick={() => (cobro.activo = false)}>Cancelar (Esc)</button>  </div></div>{/if}</div>